mapper.update:
UPDATE comment_outbox
SET state = 0, claim_token = NULL, claimed_until = NULL
WHERE state = 1 AND claimed_until < #{now}

UPDATE comment_outbox
SET state = 1, claim_token = #{claimToken}, claimed_until = #{claimedUntil}
WHERE state = 0 AND next_attempt_at <= #{now}
ORDER BY next_attempt_at, event_id
LIMIT #{limit}

UPDATE comment_outbox
SET state = 2, published_at = #{publishedAt}, claim_token = NULL,
    claimed_until = NULL, last_error = NULL
WHERE state = 1 AND claim_token = #{claimToken}
  AND event_id IN

    #{eventId}

UPDATE comment_outbox
SET state = 0,
    retry_count = CASE event_id

        WHEN #{retry.eventId} THEN #{retry.retryCount}

    END,
    next_attempt_at = CASE event_id

        WHEN #{retry.eventId} THEN #{retry.nextAttemptAt}

    END,
    last_error = CASE event_id

        WHEN #{retry.eventId} THEN #{retry.lastError}

    END,
    claim_token = NULL,
    claimed_until = NULL
WHERE state = 1 AND claim_token = #{claimToken}
  AND event_id IN

    #{retry.eventId}

mapper.delete:
DELETE FROM comment_outbox
WHERE state = 2 AND published_at < #{cutoff}
ORDER BY published_at, event_id
LIMIT #{limit}
